router.post("/alert", (req: Request, res: Response) => {
  const { sensorId, warehouseId, threshold }: { sensorId: number, warehouseId: number, threshold: number } = req.body;

  // Check for missed heartbeat
  const latestReading = getLatestReadingByWarehouse(warehouseId);
  if (!latestReading || Date.now() - latestReading.timestamp > 5000) {
    res.status(200).json({ message: "Missed heartbeat alert" });
    return;
  }

  // Check for out-of-range reading
  const readings = getReadingsBySensor(sensorId);
  const currentReading = readings[readings.length - 1];
  if (currentReading && (currentReading.value < threshold.min || currentReading.value > threshold.max)) {
    res.status(200).json({ message: "Out-of-range reading alert" });
    return;
  }

  res.status(200).json({ message: "No alerts" });
});

