import { Router, type Request, type Response } from "express";
import { Car, getAllCars, getCarById } from "../db/cars-table";
import { Booking, getBookingsByCarId } from "../db/bookings-table";

export const router = Router();

router.get("/check-availability", (req: Request, res: Response) => {
  const { startDate, endDate } = req.query;
  if (typeof startDate !== "string" || typeof endDate !== "string") {
    res.status(400).send("Invalid date format");
    return;
  }

  const cars: Car[] = getAllCars().filter(car => {
    const bookings: Booking[] = getBookingsByCarId(car.id);
    return bookings.every(booking => {
      return booking.startDate > endDate || booking.endDate < startDate;
    });
  });

  res.json(cars);
});

router.post("/book", (req: Request, res: Response) => {
  const { carId, customerId, startDate, endDate } = req.body;
  if (typeof carId !== "number" || typeof customerId !== "number" || typeof startDate !== "string" || typeof endDate !== "string") {
    res.status(400).send("Invalid input");
    return;
  }

  const car: Car | undefined = getCarById(carId);
  if (!car) {
    res.status(404).send("Car not found");
    return;
  }

  const bookings: Booking[] = getBookingsByCarId(carId);
  if (bookings.some(booking => booking.startDate <= endDate && booking.endDate >= startDate)) {
    res.status(409).send("Car is already booked for the specified date range");
    return;
  }

  insertBooking(carId, customerId, startDate, endDate);
  res.status(201).send("Booking created successfully");
});

