  // Only apply this middleware to routes related to therapy session notes
  if (!req.path.startsWith("/api/session-notes") || !["GET", "PUT"].includes(req.method)) {
    return next();
  }

  const userId = req.headers["x-user-id"] as string | undefined;
  const noteOwnerId = req.body.ownerId ?? req.query.ownerId;

  if (typeof userId !== "string" || typeof noteOwnerId !== "string") {
    res.status(400).send("User ID and note owner ID must be provided.");
    return;
  }

  if (userId !== noteOwnerId) {
    res.status(403).send("Access denied: User is not the owner of the note.");
    return;
  }

  next();
}

