  const { sku, quantity, movementType }: { sku: string, quantity: number, movementType: 'in' | 'out' } = req.body;
  logStockMovement(Number(sku), quantity, movementType);
  const stockLevel = getStockLevelBySku(sku);
  if (stockLevel) {
